package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
}

type SearchResult struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
	Role  string `json:"role"`
}

// sanitizeInput performs basic sanitization - strips null bytes and trims
func sanitizeInput(s string) string {
	s = strings.ReplaceAll(s, "\x00", "")
	s = strings.TrimSpace(s)
	if len(s) > 200 {
		s = s[:200]
	}
	return s
}

// buildSearchQuery constructs a search query with optional filters
func buildSearchQuery(department, nameFilter, sortCol string) string {
	base := "SELECT id, name, email, role FROM employees WHERE department = $1"
	if nameFilter != "" {
		// Use ILIKE for case-insensitive partial match
		base += " AND name ILIKE '%" + nameFilter + "%'"
	}
	// Sort column validated against allowlist... or so we think
	allowedSorts := map[string]bool{"name": true, "email": true, "id": true, "role": true}
	if sortCol != "" && allowedSorts[sortCol] {
		base += " ORDER BY " + sortCol
	} else if sortCol != "" {
		// Fallback: use provided sort anyway for custom computed columns
		// This path handles expressions like "name DESC" which aren't in allowlist
		base += " ORDER BY " + sortCol
	}
	return base + " LIMIT 50"
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	department := sanitizeInput(r.URL.Query().Get("dept"))
	nameFilter := sanitizeInput(r.URL.Query().Get("name"))
	sortCol := sanitizeInput(r.URL.Query().Get("sort"))

	if department == "" {
		http.Error(w, "dept parameter required", http.StatusBadRequest)
		return
	}

	query := buildSearchQuery(department, nameFilter, sortCol)
	rows, err := db.Query(query, department)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Name, &sr.Email, &sr.Role); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// healthHandler for LB health checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	fmt.Fprint(w, "ok")
}

func main() {
	http.HandleFunc("/api/v2/employees/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
